using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace OneMoreTime.EditorTools {
public static class DemoBuilder {
 public const string Root="Assets/_OneMoreTime";public static int WorldLayer;
 public static void BackupScene(string path){if(File.Exists(path)){string folder="Artifacts/SceneBackups/"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff");Directory.CreateDirectory(folder);File.Copy(path,folder+"/"+Path.GetFileName(path));var loaded=SceneManager.GetSceneByPath(path);if(loaded.IsValid()&&loaded.isDirty)EditorSceneManager.SaveScene(loaded,folder+"/Unsaved-"+Path.GetFileName(path),true);}}
 public static T Asset<T>(string name) where T:ScriptableObject {string p=Root+"/Config/"+name+".asset";var x=AssetDatabase.LoadAssetAtPath<T>(p);if(x==null){x=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(x,p);}return x;}
 public static Sprite Sprite(string path){return AssetDatabase.LoadAllAssetsAtPath("Assets/SunnyLand Artwork/"+path).OfType<Sprite>().FirstOrDefault();}
 public static int GetLayer(){var tags=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);var layers=tags.FindProperty("layers");for(int i=8;i<32;i++)if(layers.GetArrayElementAtIndex(i).stringValue=="OMTWorld")return i;for(int i=8;i<32;i++)if(layers.GetArrayElementAtIndex(i).stringValue==""){layers.GetArrayElementAtIndex(i).stringValue="OMTWorld";tags.ApplyModifiedProperties();return i;}throw new Exception("No free world layer");}
 [MenuItem("Tools/One More Time/Build or Update Demo")]
 public static void Generate(){
  if(EditorApplication.isPlaying)throw new Exception("Stop Play first");
  foreach(var s in new[]{"Config","Prefabs","Scenes","Generated"})Directory.CreateDirectory(Root+"/"+s);
  WorldLayer=GetLayer();MechanismPrefabs.Generate();var tuning=Asset<PlayerTuning>("PlayerTuning");var fox=Asset<AnimationLibrary>("FoxAnimationLibrary");
  fox.idle=Enumerable.Range(1,4).Select(i=>Sprite($"Sprites/player/idle/player-idle-{i}.png")).ToArray();fox.run=Enumerable.Range(1,6).Select(i=>Sprite($"Sprites/player/run/player-run-{i}.png")).ToArray();fox.jump=Sprite("Sprites/player/jump/player-jump-1.png");fox.fall=Sprite("Sprites/player/jump/player-fall.png");fox.visualScale=5;fox.visualOffset=new Vector2(0,.6f);EditorUtility.SetDirty(fox);
  var testFox=MakePlayer(tuning,fox);testFox.name="FoxTestPlayer";PrefabUtility.SaveAsPrefabAsset(testFox,Root+"/Prefabs/FoxTestPlayer.prefab");UnityEngine.Object.DestroyImmediate(testFox);
  var anim=GoatArtBuilder.Build();
  var player=MakePlayer(tuning,anim);PrefabUtility.SaveAsPrefabAsset(player,Root+"/Prefabs/Player.prefab");UnityEngine.Object.DestroyImmediate(player);
  string path=Root+"/Scenes/Dev_Playground.unity";
  // Additive generation preserves every open user scene and its unsaved work.
  var previous=SceneManager.GetActiveScene();BackupScene(path);var loaded=SceneManager.GetSceneByPath(path);bool wasLoaded=loaded.IsValid()&&loaded.isLoaded;var scene=wasLoaded?loaded:File.Exists(path)?EditorSceneManager.OpenScene(path,OpenSceneMode.Additive):EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);
  SceneManager.SetActiveScene(scene);
  var existing=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="OMT Managed");if(existing!=null)UnityEngine.Object.DestroyImmediate(existing);
  var root=new GameObject("OMT Managed");
  var p=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/Player.prefab"),scene);p.transform.SetParent(root.transform);p.transform.position=new Vector2(2,0);
  Ground(root.transform,"Ground",new Rect(-2,-2,30,2));Ground(root.transform,"Wall",new Rect(12,0,1,4));Ground(root.transform,"Ceiling",new Rect(5,2,3,.4f));Ground(root.transform,"Platform",new Rect(16,0,4,2));
  var cam=new GameObject("Camera").AddComponent<Camera>();cam.transform.SetParent(root.transform);cam.orthographic=true;cam.orthographicSize=5.5f;cam.transform.position=new Vector3(9,3,-10);cam.backgroundColor=new Color(.14f,.24f,.30f);cam.clearFlags=CameraClearFlags.SolidColor;cam.gameObject.AddComponent<AudioListener>();
  var driver=root.AddComponent<PlaygroundDriver>();driver.player=p.GetComponent<PlayerMotor2D>();driver.visual=p.GetComponentInChildren<PlayerVisual>();driver.view=cam;driver.goat=anim;driver.fox=fox;
  EditorSceneManager.SaveScene(scene,path);if(!wasLoaded)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(previous);BuildLevelOne(tuning,anim);BuildLevelThree();BuildLevelTwo();BuildLevelFour();PresentationBuilder.Menus();AssetDatabase.SaveAssets();
  File.WriteAllText("Artifacts/Logs/generate.txt","Generated Stage 1 playground, Player prefab, PlayerTuning and AnimationLibrary. "+DateTime.UtcNow);
 }
 public static void BuildLevelOne(PlayerTuning tuning,AnimationLibrary anim){
  var cfg=Asset<LevelConfig>("L01_Freeze");if(!cfg.initialized){cfg.terrain=new[]{new Rect(-2,-2,15,2),new Rect(13,-2,8,6.5f),new Rect(-2,0,1,12)};cfg.initialized=true;}EditorUtility.SetDirty(cfg);
  var e=new GameObject("FreezeEcho");var es=e.AddComponent<EchoSurface>();var v=new GameObject("Visual");v.transform.SetParent(e.transform);es.visual=v.AddComponent<PlayerVisual>();es.visual.library=anim;var im=new GameObject("Sprite");im.transform.SetParent(v.transform);im.transform.localPosition=anim.visualOffset;im.transform.localScale=Vector3.one*anim.visualScale;es.visual.renderer2D=im.AddComponent<SpriteRenderer>();es.visual.renderer2D.sprite=anim.idle[0];es.visual.renderer2D.sortingOrder=9;
  var line=new GameObject("Support");line.transform.SetParent(v.transform);line.transform.localPosition=Vector2.up*tuning.backHeight;es.support=line.AddComponent<SpriteRenderer>();es.support.sprite=PresentationBuilder.White();es.support.drawMode=SpriteDrawMode.Sliced;es.support.size=new Vector2(tuning.backWidth,.055f);es.support.color=Color.cyan;es.support.sortingOrder=11;
  PrefabUtility.SaveAsPrefabAsset(e,Root+"/Prefabs/FreezeEcho.prefab");UnityEngine.Object.DestroyImmediate(e);
  BuildLevel(cfg,"L01_Freeze");
 }
 public static void BuildLevelThree(){var cfg=Asset<LevelConfig>("L03_Trace");if(!cfg.initialized){cfg.level=3;cfg.title="跳上昨天";cfg.hint="先等一下，再跳。Q 保存最近最多 10 秒；下一次的你需要時間站上來。";cfg.goal=new Rect(19,6.3f,1,2);cfg.cameraSize=6.5f;cfg.terrain=new[]{new Rect(-2,-2,16,2),new Rect(14,-2,8,8.3f),new Rect(-2,0,1,14)};cfg.initialized=true;}EditorUtility.SetDirty(cfg);BuildLevel(cfg,"L03_Trace");}
 public static void BuildLevelTwo(){var cfg=Asset<LevelConfig>("L02_Pressure");if(!cfg.initialized){cfg.level=2;cfg.title="幫我留在這裡";cfg.hint="站在踏板上按 E。留下的你，既能開門，也能墊高。";cfg.goal=new Rect(18,3.5f,1,2);cfg.terrain=new[]{new Rect(-2,-2,14,2),new Rect(12,-2,9,5.5f),new Rect(12,7,9,1),new Rect(-2,0,1,12),new Rect(21,0,1,12)};cfg.plates=new[]{new Vector2(10.8f,0)};cfg.doors=new[]{new Rect(13,3.5f,.6f,3.5f)};cfg.initialized=true;}EditorUtility.SetDirty(cfg);BuildLevel(cfg,"L02_Pressure");}
 public static void BuildLevelFour(){var cfg=Asset<LevelConfig>("L04_Timing");if(!cfg.initialized){cfg.level=4;cfg.title="這次換你等我";cfg.hint="先走下層，在 A、B 各等一下，再按 Q 保存。利用輪從上層通過。";cfg.spawn=new Vector2(2,5);TimingLayout(cfg);cfg.initialized=true;}EditorUtility.SetDirty(cfg);BuildLevel(cfg,"L04_Timing");}
 static void TimingLayout(LevelConfig cfg){cfg.goal=new Rect(34,5,1,2);cfg.cameraSize=7;cfg.cameraMax=28;cfg.terrain=new[]{new Rect(-2,-2,40,2),new Rect(-2,0,1,12),new Rect(37,0,1,12),new Rect(-2,4.5f,5,.5f),new Rect(5,4.5f,14,.5f),new Rect(23,4.5f,14,.5f),new Rect(5,3.5f,32,1),new Rect(5,10,32,1)};cfg.plates=new[]{new Vector2(6,0),new Vector2(18,0)};cfg.doors=new[]{new Rect(16,5,.6f,5),new Rect(30,5,.6f,5)};cfg.crumbles=new[]{new Rect(19,4.8f,2,.2f),new Rect(21,4.8f,2,.2f)};cfg.hazards=new[]{new Rect(19,4.45f,4,.28f)};}
 public static void ReviseTimingLayout(){var cfg=Asset<LevelConfig>("L04_Timing");TimingLayout(cfg);EditorUtility.SetDirty(cfg);AssetDatabase.SaveAssets();Generate();}
 public static void BuildLevel(LevelConfig cfg,string name){
  string path=Root+"/Scenes/"+name+".unity";var prev=SceneManager.GetActiveScene();BackupScene(path);var loaded=SceneManager.GetSceneByPath(path);bool wasLoaded=loaded.IsValid()&&loaded.isLoaded;var scene=wasLoaded?loaded:File.Exists(path)?EditorSceneManager.OpenScene(path,OpenSceneMode.Additive):EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);
  var old=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="OMT Managed");if(old!=null)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("OMT Managed");
  var p=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/Player.prefab"),scene);p.transform.SetParent(root.transform);p.transform.position=cfg.spawn;
  var ghost=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/FreezeEcho.prefab"),scene);ghost.transform.SetParent(root.transform);
  foreach(var r in cfg.terrain){var ground=new GameObject("Terrain");ground.transform.SetParent(root.transform);ground.layer=WorldLayer;ground.transform.position=r.center;ground.AddComponent<BoxCollider2D>().size=r.size;}
  TerrainArtBuilder.Build(root.transform,cfg);
  foreach(var r in cfg.crumbles){var g=MechanismPrefabs.Spawn("CrumblingPlatform",root.transform);g.transform.position=r.center;var crumble=g.GetComponent<CrumblingPlatform>();crumble.solid.size=r.size;crumble.graphic.size=r.size;}
  var spike=SpikeArtBuilder.EnsureSprite();foreach(var r in cfg.hazards)SpikeArtBuilder.Create(root.transform,r,spike);
  var plates=new PressurePlate[cfg.plates.Length];for(int i=0;i<plates.Length;i++){var plate=MechanismPrefabs.Spawn("PressurePlate",root.transform);plate.name="Plate "+(char)('A'+i);plate.transform.position=cfg.plates[i];plates[i]=plate.GetComponent<PressurePlate>();plates[i].graphic.sprite=PresentationBuilder.White();plates[i].graphic.drawMode=SpriteDrawMode.Sliced;plates[i].graphic.size=new Vector2(1.4f,.12f);plates[i].graphic.sortingOrder=3;}
  for(int i=0;i<cfg.doors.Length;i++){var d=MechanismPrefabs.Spawn("LinkedDoor",root.transform);d.name="Door "+(char)('A'+i);d.transform.position=cfg.doors[i].center;d.GetComponent<BoxCollider2D>().size=cfg.doors[i].size;d.GetComponent<SpriteRenderer>().size=cfg.doors[i].size;var linked=d.GetComponent<LinkedDoor>();linked.plate=plates[cfg.DoorSource(i)];linked.solid=d.GetComponent<BoxCollider2D>();linked.graphic=d.GetComponent<SpriteRenderer>();}
  var door=new GameObject("Goal");door.transform.SetParent(root.transform);door.transform.position=cfg.goal.center;var ds=door.AddComponent<SpriteRenderer>();ds.sprite=Sprite("Environment/props/door.png");door.transform.localScale=Vector3.one*5;door.transform.position=new Vector2(cfg.goal.center.x,cfg.goal.yMin+ds.sprite.bounds.extents.y*5);ds.sortingOrder=5;
  var c=new GameObject("Camera").AddComponent<Camera>();c.transform.SetParent(root.transform);c.orthographic=true;c.orthographicSize=cfg.cameraSize;c.transform.position=new Vector3(10,3.5f,-10);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.12f,.24f,.31f);c.gameObject.AddComponent<AudioListener>();
  var run=root.AddComponent<RunManager>();run.config=cfg;run.player=p.GetComponent<PlayerMotor2D>();run.visual=p.GetComponentInChildren<PlayerVisual>();run.echo=ghost.GetComponent<EchoSurface>();run.view=c;PresentationBuilder.Decorate(root,cfg,c);
  EditorSceneManager.SaveScene(scene,path);if(!wasLoaded)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(prev);
 }
 public static GameObject MakePlayer(PlayerTuning tuning,AnimationLibrary anim){var go=new GameObject("Player");var motor=go.AddComponent<PlayerMotor2D>();motor.tuning=tuning;motor.worldMask=1<<WorldLayer;var body=go.GetComponent<Rigidbody2D>();body.bodyType=RigidbodyType2D.Kinematic;body.gravityScale=0;body.constraints=RigidbodyConstraints2D.FreezeRotation;var c=go.GetComponent<BoxCollider2D>();c.size=new Vector2(.7f,1);c.offset=Vector2.up*.5f;var visual=new GameObject("Visual");visual.transform.SetParent(go.transform);var pv=visual.AddComponent<PlayerVisual>();pv.library=anim;var image=new GameObject("Sprite");image.transform.SetParent(visual.transform);image.transform.localPosition=anim.visualOffset;image.transform.localScale=Vector3.one*anim.visualScale;pv.renderer2D=image.AddComponent<SpriteRenderer>();pv.renderer2D.sprite=anim.idle[0];pv.renderer2D.sortingOrder=10;return go;}
 public static GameObject Ground(Transform parent,string name,Rect rect){var go=new GameObject(name);go.transform.SetParent(parent);go.layer=WorldLayer;go.transform.position=rect.center;go.AddComponent<BoxCollider2D>().size=rect.size;PresentationBuilder.TerrainSkin(go,rect,name);
  return go;}
 [MenuItem("Tools/One More Time/Validate Demo")]
 public static void Validate(){int missing=0,count=0;foreach(var path in AssetDatabase.FindAssets("t:Prefab",new[]{Root}).Select(AssetDatabase.GUIDToAssetPath)){var go=AssetDatabase.LoadAssetAtPath<GameObject>(path);foreach(var t in go.GetComponentsInChildren<Transform>(true))missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);count++;}var a=AssetDatabase.LoadAssetAtPath<AnimationLibrary>(Root+"/Config/AnimationLibrary.asset");if(a==null||a.idle.Any(s=>s==null)||a.run.Any(s=>s==null)||a.jump==null||a.fall==null)throw new Exception("Missing animation reference");if(missing>0)throw new Exception("Missing scripts: "+missing);SceneValidator.Validate();File.WriteAllText("Artifacts/Logs/validate.txt",$"PASS: {count} prefabs; missing scripts={missing}; all 12 animation references valid; Unity {Application.unityVersion}");}
 [MenuItem("Tools/One More Time/Open Playground")]
 public static void OpenPlayground(){EditorSceneManager.OpenScene(Root+"/Scenes/Dev_Playground.unity",OpenSceneMode.Additive);}
 [MenuItem("Tools/One More Time/Audit Assets")]
 public static void Audit(){File.WriteAllText("Artifacts/Logs/assets.txt",string.Join("\n",AssetDatabase.FindAssets("t:Sprite",new[]{"Assets/SunnyLand Artwork"}).Select(AssetDatabase.GUIDToAssetPath)));}
}
}
